import { z } from 'zod';
import { locales } from '@/content/types';
import { PROFILE_TYPES, UTM_KEYS } from './options';

/**
 * Shared lead schema (PRD §18–19) — used by the form (client) and the API route (server).
 * Error messages are stable codes, translated via connect.form.errors.
 */
export type ErrorCode = 'required' | 'email' | 'url' | 'consent' | 'tooLong';
/** The review form adds a minimum length. */
export type ReviewErrorCode = ErrorCode | 'tooShort';

/** Random UUID generated by the form when it opens; the database ignores a second submission with the same key. */
const idempotencyKey = z.string({ required_error: 'required', invalid_type_error: 'required' }).uuid('required');

const required = (max: number) =>
  z
    .string({ required_error: 'required', invalid_type_error: 'required' })
    .trim()
    .min(1, 'required')
    .max(max, 'tooLong');

/** Website or LinkedIn URL. Accepts "azienda.it" and normalises to "https://azienda.it/". Empty → undefined. */
const optionalUrl = z
  .string()
  .trim()
  .max(300, 'tooLong')
  .optional()
  .transform((value, ctx) => {
    if (!value) return undefined;
    const withProtocol = /^https?:\/\//i.test(value) ? value : `https://${value}`;
    try {
      const url = new URL(withProtocol);
      if (!url.hostname.includes('.')) throw new Error('invalid');
      return url.toString();
    } catch {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'url' });
      return z.NEVER;
    }
  });

const applicationSchema = z.object({
  startupName: required(120),
  companyIncorporated: z.enum(['yes', 'no']),
  incorporationYear: z.string().trim().regex(/^\d{4}$/, 'required').optional(),
  cityProvince: required(120),
  sector: required(200),
  websites: z.array(z.string().trim().url('url').max(300, 'tooLong')).max(5).optional(),
  serviceInterest: z.enum(['business-plan', 'fundraising', 'business-development', 'other']),
  otherService: z.string().trim().max(200, 'tooLong').optional(),
});

export const leadSchema = z.object({
  locale: z.enum(locales),
  firstName: required(80),
  lastName: required(80),
  email: z
    .string({ required_error: 'required' })
    .trim()
    .toLowerCase()
    .min(1, 'required')
    .max(254, 'tooLong')
    .email('email'),
  company: required(120),
  role: required(120),
  link: optionalUrl,
  profileType: z.enum(PROFILE_TYPES, { errorMap: () => ({ message: 'required' }) }),
  interest: z
    .string()
    .trim()
    .max(1000, 'tooLong')
    .optional()
    .transform((v) => (v ? v : undefined)),
  application: applicationSchema.optional(),
  submissionType: z.enum(['pitch', 'cv']).optional(),
  consent: z.literal(true, { errorMap: () => ({ message: 'consent' }) }),
  utm: z.record(z.enum(UTM_KEYS), z.string().max(200)).optional(),
  // Anti-spam signals (never stored)
  company_website_hp: z.string().max(0).optional(),
  elapsedMs: z.number().int().nonnegative().optional(),
});

export type LeadInput = z.input<typeof leadSchema>;
export type Lead = z.output<typeof leadSchema>;

/** "Connettiti con Rainmakers" → POST /api/lead → contact_requests. Never a marketing subscription. */
export const contactSchema = leadSchema.omit({ application: true, submissionType: true }).extend({ idempotencyKey });
export type ContactSubmission = z.output<typeof contactSchema>;

/** "Entra su WhatsApp" → POST /api/community → community_requests, then the WhatsApp link is returned. */
export const communitySchema = z.object({
  locale: z.enum(locales),
  firstName: required(80),
  email: z.string({ required_error: 'required' }).trim().toLowerCase().min(1, 'required').max(254, 'tooLong').email('email'),
  community: z.string().regex(/^[a-z0-9-]{1,60}$/, 'required'),
  consent: z.literal(true, { errorMap: () => ({ message: 'consent' }) }),
  utm: z.record(z.enum(UTM_KEYS), z.string().max(200)).optional(),
  website_hp: z.string().max(0).optional(),
  elapsedMs: z.number().int().nonnegative().optional(),
});
export type CommunitySubmission = z.output<typeof communitySchema>;

/** "Lascia una review" (POST /api/review → reviews, email to the team inbox). Privacy consent required. */
export const reviewSchema = z.object({
  locale: z.enum(locales),
  name: required(120),
  email: z.string({ required_error: 'required' }).trim().toLowerCase().min(1, 'required').max(254, 'tooLong').email('email'),
  company: z.string().trim().max(120, 'tooLong').optional(),
  role: z.string().trim().max(120, 'tooLong').optional(),
  rating: z.number().int().min(1).max(5).optional(),
  review: z.string({ required_error: 'required' }).trim().min(1, 'required').min(20, 'tooShort').max(1500, 'tooLong'),
  publishConsent: z.boolean().optional(),
  consent: z.literal(true, { errorMap: () => ({ message: 'consent' }) }),
  idempotencyKey,
  utm: z.record(z.enum(UTM_KEYS), z.string().max(200)).optional(),
  company_website_hp: z.string().max(0).optional(),
  elapsedMs: z.number().int().nonnegative().optional(),
});
export type ReviewSubmission = z.output<typeof reviewSchema>;

/** Flattens zod issues into { field: code } (first issue per field). */
export function toFieldErrors(error: z.ZodError): Record<string, ErrorCode> {
  const out: Record<string, ErrorCode> = {};
  for (const issue of error.issues) {
    const key = String(issue.path[0] ?? 'form');
    if (!out[key]) out[key] = (issue.message as ErrorCode) || 'required';
  }
  return out;
}
